// Heurística de Nielsen 9: 50 problemas aprofundados pela UBERTRIZ
window.PROBLEMAS.push(
{"id":401,"h":9,"sev":3,"t":"Erro com código técnico","sym":"O app da câmera de segurança exibe “Erro 0x80070005 — ACCESS_DENIED”.","ten":"O código ajuda a equipe técnica, mas não quem está na frente da tela.","sol":"Converter o meio: dizer o que houve, por quê e como resolver em linguagem humana; o código fica em “detalhes técnicos” recolhidos.","c":"C35","u":"U16","e":"meso","i":"I09","m":"Chamados após o erro","freq":3,"imp":2,"pers":2,"pf":"P01","hx":["BS5.2","GP2","WC3.3","SH3","ISO6","MB8"],"dom":"casa","vul":"","ag":"Ganha: quem usa a câmera da casa e o suporte, que recebe menos chamados. Perde: a equipe escreve e mantém um catálogo de mensagens.","alt":"E se o erro aparecer tanto que o problema seja a falha em si, e não a mensagem?","esc":{"micro":"Mensagem humana no lugar do código.","meso":"Converter o meio: dizer o que houve, por quê e como resolver em linguagem humana; o código fica em “detalhes técnicos” recolhidos.","macro":"Catálogo de erros com causa, efeito e solução, usado por todos os aparelhos da marca."},"st":"add","sub":"Retirar o código técnico da primeira linha da mensagem.","ops":["U09","U18"],"c2":{"c":"C34","t":"Esconder o código dificulta o atendimento técnico.","mit":"Código em “detalhes técnicos” recolhidos, com botão de copiar."},"cf":"Sem intervenção, a pessoa reinicia o aparelho várias vezes e liga para o suporte.","lim":{"l":"L03","t":"O firmware precisa ser atualizado para trazer as mensagens novas."},"ide":{"mais":["I09","I07"],"menos":["I03"]},"ref":"Estaria errada se, depois das mensagens humanas, os chamados sobre esse erro não diminuírem.","conf":"alta"},
{"id":402,"h":9,"sev":3,"t":"Erro longe do campo","sym":"No portal, “Há erros no formulário” aparece no topo; o campo errado está três telas abaixo.","ten":"O aviso geral informa, mas não localiza.","sol":"Separar no espaço de forma útil: mensagem junto ao campo e resumo no topo com links para cada erro.","c":"C10","u":"U07","e":"micro","i":"I02","m":"Tempo para corrigir o formulário","freq":3,"imp":2,"pers":2,"pf":"P01","hx":["BS5.2","WC3.3","BS1.2","GP10","SH3"],"dom":"publico","vul":"","ag":"Ganha: cidadãos que preenchem formulários longos. Perde: mensagens em cada campo e no topo duplicam a informação.","alt":"E se os erros forem tantos que a própria validação esteja rigorosa demais?","esc":{"micro":"Separar no espaço de forma útil: mensagem junto ao campo e resumo no topo com links para cada erro.","meso":"Resumo no topo com links que levam a cada campo com erro.","macro":"Padrão de erros de formulário no design system do governo."},"st":"add","sub":"Retirar a mensagem genérica solitária no topo.","ops":["U12","U01"],"c2":{"c":"C17","t":"Mensagens em cada campo e no topo duplicam a informação.","mit":"Resumo curto no topo; detalhe só no campo."},"cf":"Sem intervenção, a pessoa rola a página procurando o erro e desiste.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I02"],"menos":["I03"]},"ref":"Estaria errada se, em teste, o tempo para corrigir não cair com mensagens junto ao campo.","conf":"alta"},
{"id":403,"h":9,"sev":4,"t":"Formulário apagado após o erro","sym":"Na inscrição do curso, um CPF inválido e todos os 20 campos voltam em branco.","ten":"A validação protege o sistema, mas destrói o trabalho de quem preenche.","sol":"Preservar tudo o que foi digitado e destacar só o campo com problema.","c":"C18","u":"U24","e":"micro","i":"I10","m":"Abandono após erro","freq":2,"imp":3,"pers":2,"pf":"P01","hx":["BS5.3","TG13","SH6","ISO6","LX8"],"dom":"educacao","vul":"deficiência motora","ag":"Ganha: estudantes, sobretudo quem digita com dificuldade. Perde: nada relevante.","alt":"E se o formulário for apagado porque a página recarrega inteira ao validar no servidor?","esc":{"micro":"Preservar tudo o que foi digitado e destacar só o campo com problema.","meso":"Validação no navegador antes de enviar.","macro":"Padrão: nenhum formulário da plataforma apaga dados em caso de erro."},"st":"sub","sub":"A própria solução é subtrativa: remove a limpeza do formulário após o erro.","ops":["U19","U36"],"c2":{"c":"C05","t":"Preservar dados sensíveis (senha) na tela pode expô-los.","mit":"Preservar tudo, exceto senhas."},"cf":"Sem intervenção, estudantes desistem da inscrição depois de redigitar 20 campos.","lim":{"l":"L03","t":"Arquitetura de validação no servidor."},"ide":{"mais":["I10"],"menos":[]},"ref":"Estaria errada se, nos registros, as desistências após erro forem raras.","conf":"alta"},
{"id":404,"h":9,"sev":3,"t":"“Algo deu errado”","sym":"No assistente de IA, a resposta a qualquer falha é “Algo deu errado”.","ten":"A falha tem muitas causas possíveis, mas a pessoa precisa de um próximo passo.","sol":"Reenquadrar a falha em próximo passo: mensagem específica, ação clara (reformular, tentar depois) e código para o suporte.","c":"C34","u":"U04","e":"meso","i":"I09","m":"Tentativas até concluir após falha","freq":3,"imp":2,"pers":2,"pf":"P04","hx":["BS5.2","GP2","IA2","IA10","SH3"],"dom":"ia","vul":"","ag":"Ganha: quem usa o assistente. Perde: a equipe precisa classificar as falhas.","alt":"E se as falhas forem genéricas porque nem a equipe sabe por que o assistente falha?","esc":{"micro":"Mensagem com o tipo de falha e sugestão de reformular.","meso":"Reenquadrar a falha em próximo passo: mensagem específica, ação clara (reformular, tentar depois) e código para o suporte.","macro":"Monitoramento das falhas por tipo, com correções priorizadas."},"st":"add","sub":"Retirar a mensagem “Algo deu errado” como resposta padrão.","ops":["U03","U19"],"c2":{"c":"C05","t":"Explicar a falha pode revelar limitações que a empresa preferia esconder.","mit":"Honestidade sobre limites aumenta a confiança."},"cf":"Sem intervenção, a pessoa repete a pergunta várias vezes e desiste do assistente.","lim":{"l":"L03","t":"Nem toda falha do modelo é diagnosticável."},"ide":{"mais":["I09"],"menos":["I03"]},"ref":"Estaria errada se, em teste, as pessoas não conseguirem agir melhor com mensagens específicas.","conf":"média"},
{"id":405,"h":9,"sev":3,"t":"Mensagem que culpa","sym":"No app do banco: “Você digitou errado! Dados inválidos!”","ten":"O sistema quer ser claro, mas o tom acusa.","sol":"Reenquadrar o tom: neutro e construtivo — “O CPF tem 11 dígitos. Confira os números.”","c":"C26","u":"U04","e":"micro","i":"I06","m":"Satisfação após erros","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS5.2","IA5","SH3","ISO7","WC3.3"],"dom":"financas","vul":"baixa escolaridade","ag":"Ganha: clientes, sobretudo quem já se sente inseguro com tecnologia. Perde: nada relevante.","alt":"E se o tom acusatório vier de mensagens escritas por desenvolvedores sob pressão?","esc":{"micro":"Reenquadrar o tom: neutro e construtivo — “O CPF tem 11 dígitos. Confira os números.”","meso":"Revisão de todas as mensagens de erro do app com o guia de tom.","macro":"Guia de voz e tom com exemplos para mensagens de erro."},"st":"mod","sub":"Retirar exclamações e acusações das mensagens.","ops":["U32","U30"],"c2":{"c":"C35","t":"Mensagens gentis demais podem esconder o problema.","mit":"Neutras e específicas: o que houve e como corrigir."},"cf":"Sem intervenção, clientes se sentem humilhados e abandonam o app.","lim":{"l":"L06","t":"Mensagens espalhadas por vários sistemas."},"ide":{"mais":["I06"],"menos":[]},"ref":"Estaria errada se, em pesquisa, as pessoas não perceberem diferença de tom.","conf":"alta"},
{"id":406,"h":9,"sev":2,"t":"Página 404 sem saída","sym":"“Página não encontrada” e nada mais na loja.","ten":"O link quebrou, mas a intenção da pessoa continua válida.","sol":"Redundar caminhos: 404 com busca, links mais procurados e produtos similares.","c":"C10","u":"U22","e":"micro","i":"I08","m":"Saídas do site a partir da 404","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["BS5.3","TG8","WC2.4","ISO6"],"dom":"comercio","vul":"","ag":"Ganha: quem chega por links antigos. Perde: links demais na 404 confundem.","alt":"E se a 404 vier de produtos retirados sem redirecionamento?","esc":{"micro":"Redundar caminhos: 404 com busca, links mais procurados e produtos similares.","meso":"Redirecionar produtos retirados para similares.","macro":"Monitoramento de links quebrados vindos de fora."},"st":"add","sub":"Retirar a página 404 sem nenhuma saída.","ops":["U02","U36"],"c2":{"c":"C17","t":"Links demais na 404 confundem.","mit":"Busca e três links mais procurados."},"cf":"Sem intervenção, quem chega por um link antigo sai da loja.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I08"],"menos":["I03"]},"ref":"Estaria errada se, nos registros, as saídas pela 404 forem raras.","conf":"alta"},
{"id":407,"h":9,"sev":4,"t":"Pagamento recusado sem motivo","sym":"No pagamento: “Transação não autorizada.” A pessoa tenta o mesmo cartão cinco vezes.","ten":"O motivo vem do banco em código, mas quem paga precisa saber o que fazer.","sol":"Reacoplar a informação do banco ao cliente: motivo provável em linguagem simples e alternativas (outro cartão, Pix, boleto).","c":"C12","u":"U12","e":"macro","i":"I04","m":"Vendas recuperadas após recusa","freq":3,"imp":3,"pers":2,"pf":"P04","hx":["BS5.2","GP2","SH3","ISO6","DP3"],"dom":"comercio","vul":"","ag":"Ganha: clientes e a loja, que recupera vendas. Perde: integrar motivos de recusa com os bancos tem custo.","alt":"E se o banco emissor não informar o motivo à loja?","esc":{"micro":"Mensagem com os motivos mais comuns e alternativas.","meso":"Oferecer Pix ou outro cartão na mesma tela.","macro":"Reacoplar a informação do banco ao cliente: motivo provável em linguagem simples e alternativas (outro cartão, Pix, boleto)."},"st":"add","sub":"Retirar a mensagem crua “Transação não autorizada”.","ops":["U22","U20"],"c2":{"c":"C05","t":"Dar o motivo exato pode ajudar fraudadores.","mit":"Motivo genérico por categoria, sem detalhes exploráveis."},"cf":"Sem intervenção, o cliente tenta o mesmo cartão cinco vezes e desiste da compra.","lim":{"l":"L06","t":"Regras dos bancos sobre informar o motivo."},"ide":{"mais":["I04"],"menos":["I05"]},"ref":"Estaria errada se, nos registros, as vendas recuperadas após recusa não aumentarem.","conf":"média"},
{"id":408,"h":9,"sev":4,"t":"Erro indicado só pela cor","sym":"No formulário do hospital, o campo com erro só fica com borda vermelha.","ten":"A cor é rápida, mas não chega a todos.","sol":"Redundância de sinais: ícone + texto + cor.","c":"C25","u":"U22","e":"micro","i":"I06","m":"Erros não percebidos","freq":2,"imp":3,"pers":2,"pf":"P01","hx":["TG3","WC1.4","WC1.3","GP9","BS5.2"],"dom":"saude","vul":"daltonismo","ag":"Ganha: pessoas com daltonismo e quem usa leitor de tela. Perde: ícones e textos em cada campo poluem.","alt":"E se o erro não for percebido porque aparece longe de onde se olha?","esc":{"micro":"Redundância de sinais: ícone + texto + cor.","meso":"Padrão de erro com ícone, texto e cor em todos os formulários.","macro":"Auditoria de acessibilidade dos sistemas do hospital."},"st":"add","sub":"Retirar a cor como único sinal de erro.","ops":["U01","U30"],"c2":{"c":"C17","t":"Ícones e textos em cada campo poluem.","mit":"Só nos campos com erro."},"cf":"Sem intervenção, pacientes enviam formulários com erro sem perceber.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I06"],"menos":["I03"]},"ref":"Estaria errada se, em teste com daltônicos, os erros forem percebidos só pela cor.","conf":"alta"},
{"id":409,"h":9,"sev":4,"t":"Sessão expira e leva o trabalho","sym":"Depois de 30 minutos escrevendo um recurso no portal, “Sessão expirada” — tudo perdido.","ten":"A sessão precisa expirar por segurança, mas o trabalho precisa sobreviver.","sol":"Antecipar: política de sessão com aviso antes de expirar, extensão com um clique e restauração do conteúdo após novo login.","c":"C33","u":"U20","e":"macro","i":"I10","m":"Trabalho perdido por expiração","freq":2,"imp":3,"pers":3,"pf":"P06","hx":["TG13","WC2.2","BS5.3","SH2","MB8"],"dom":"publico","vul":"idosos","ag":"Ganha: cidadãos que escrevem devagar, sobretudo idosos. Perde: sessões mais longas pedem outras proteções.","alt":"E se a sessão curta for exigência de segurança mal calibrada para o risco do serviço?","esc":{"micro":"Aviso dois minutos antes de expirar.","meso":"Estender com um clique e salvar rascunho automaticamente.","macro":"Antecipar: política de sessão com aviso antes de expirar, extensão com um clique e restauração do conteúdo após novo login."},"st":"mod","sub":"Retirar a expiração por tempo fixo em serviços de baixo risco.","ops":["U24","U21"],"c2":{"c":"C05","t":"Sessões longas aumentam o risco em computadores públicos.","mit":"Expiração por inatividade real, com rascunho restaurável após novo login."},"cf":"Sem intervenção, textos longos (recursos, requerimentos) se perdem e o cidadão desiste.","lim":{"l":"L06","t":"Normas de segurança da informação do órgão."},"ide":{"mais":["I10"],"menos":["I05"]},"ref":"Estaria errada se, nos registros, as expirações ocorrerem com a pessoa ausente, e não escrevendo.","conf":"alta"},
{"id":410,"h":9,"sev":3,"t":"Busca vazia sem sugestão","sym":"“Nenhum resultado para ‘tenis corida’.”","ten":"O termo exato não existe, mas a intenção é clara.","sol":"Corrigir (“Você quis dizer tênis corrida?”), sugerir termos próximos e ampliar filtros.","c":"C04","u":"U02","e":"micro","i":"I08","m":"Buscas que terminam sem clique","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS5.3","IA9","GP1","LX7"],"dom":"comercio","vul":"","ag":"Ganha: quem busca com erros de digitação. Perde: correção automática pode trocar o que a pessoa quis dizer.","alt":"E se a busca vazia vier de produtos que a loja não tem?","esc":{"micro":"Corrigir (“Você quis dizer tênis corrida?”), sugerir termos próximos e ampliar filtros.","meso":"Termos populares e categorias relacionadas na página vazia.","macro":"Análise das buscas sem resultado para decidir o que vender."},"st":"add","sub":"Retirar a página vazia sem nenhuma sugestão.","ops":["U34","U19"],"c2":{"c":"C27","t":"Correção automática pode trocar o que a pessoa quis dizer.","mit":"Sugerir, sem trocar, e mostrar os resultados originais."},"cf":"Sem intervenção, a pessoa conclui que a loja não tem o produto.","lim":{"l":"L03","t":"Qualidade do índice de busca."},"ide":{"mais":["I08"],"menos":["I03"]},"ref":"Estaria errada se as buscas sem resultado forem por produtos que a loja não vende.","conf":"alta"},
{"id":411,"h":9,"sev":3,"t":"Validação só no envio","sym":"No formulário de matrícula, depois de preencher tudo, surgem oito erros de uma vez.","ten":"Validar no fim é simples, mas acumula frustração.","sol":"Retroalimentar no momento certo: validar cada campo ao sair dele, com mensagem imediata e específica.","c":"C33","u":"U19","e":"micro","i":"I02","m":"Erros no envio","freq":3,"imp":2,"pers":2,"pf":"P01","hx":["BS1.4","BS5.1","WC3.3","SH5","LX6"],"dom":"educacao","vul":"","ag":"Ganha: estudantes. Perde: validar enquanto a pessoa digita mostra erro antes de ela terminar.","alt":"E se a validação imediata interromper quem ainda está digitando?","esc":{"micro":"Retroalimentar no momento certo: validar cada campo ao sair dele, com mensagem imediata e específica.","meso":"Validação ao sair do campo em todos os formulários da plataforma.","macro":"Padrão de validação no design system."},"st":"add","sub":"Retirar a validação concentrada no envio.","ops":["U20","U21"],"c2":{"c":"C32","t":"Validar enquanto a pessoa digita mostra erro antes de ela terminar.","mit":"Validar ao sair do campo, não a cada tecla."},"cf":"Sem intervenção, oito erros aparecem de uma vez no envio e a pessoa desanima.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I02"],"menos":["I03"]},"ref":"Estaria errada se, nos registros, os envios com erro forem raros.","conf":"alta"},
{"id":412,"h":9,"sev":3,"t":"Qual arquivo falhou?","sym":"No sistema de documentos: “Falha no envio” — mas foram enviados 12 arquivos.","ten":"O erro é de um item, mas a mensagem é do lote.","sol":"Indicar o arquivo com problema, o motivo e reenviar só ele.","c":"C13","u":"U01","e":"micro","i":"I09","m":"Reenvios completos","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS5.2","GP3","SH3","MB8"],"dom":"trabalho","vul":"","ag":"Ganha: quem envia vários arquivos. Perde: mensagem por arquivo em lotes grandes vira lista enorme.","alt":"E se o envio em lote falhar por um limite que ninguém informou?","esc":{"micro":"Indicar o arquivo com problema, o motivo e reenviar só ele.","meso":"Lista de envios com o estado de cada arquivo.","macro":"Limites informados antes de começar o envio."},"st":"add","sub":"Retirar a mensagem única para o lote inteiro.","ops":["U09","U31"],"c2":{"c":"C17","t":"Mensagem por arquivo em lotes grandes vira lista enorme.","mit":"Agrupar por tipo de erro."},"cf":"Sem intervenção, todos os arquivos são reenviados por causa de um.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I09"],"menos":["I03"]},"ref":"Estaria errada se, nos registros, os lotes com falha forem raros.","conf":"alta"},
{"id":413,"h":9,"sev":3,"t":"Login incorreto sem caminho","sym":"No app do banco: “E-mail ou senha incorretos” e nenhuma saída.","ten":"Não revelar qual está errado protege a conta, mas deixa a pessoa sem rumo.","sol":"Redundar caminhos sem revelar o que está errado: mensagem neutra com links visíveis para recuperar senha e conferir o e-mail.","c":"C23","u":"U22","e":"micro","i":"I05","m":"Recuperações bem-sucedidas","freq":3,"imp":2,"pers":2,"pf":"P09","hx":["BS5.2","BS5.3","SH5","ISO6","WC3.3"],"dom":"financas","vul":"","ag":"Ganha: clientes que erram o login. Perde: dizer qual dado está errado ajuda ataques.","alt":"E se o login falhar tanto porque a pessoa não sabe qual e-mail usou?","esc":{"micro":"Redundar caminhos sem revelar o que está errado: mensagem neutra com links visíveis para recuperar senha e conferir o e-mail.","meso":"Opção de entrar por CPF e recuperar o e-mail.","macro":"Chave de acesso sem senha como alternativa."},"st":"add","sub":"Retirar o beco sem saída depois do erro.","ops":["U04","U16"],"c2":{"c":"C05","t":"Dizer qual dado está errado ajuda ataques.","mit":"Mensagem neutra e caminhos de recuperação claros."},"cf":"Sem intervenção, clientes bloqueiam a conta tentando adivinhar.","lim":{"l":"L06","t":"Normas de segurança bancária."},"ide":{"mais":["I05"],"menos":["I02"]},"ref":"Estaria errada se, nos registros, a recuperação de senha já for usada logo após o erro.","conf":"alta"},
{"id":414,"h":9,"sev":4,"t":"Conta bloqueada sem instrução","sym":"Na rede social: “Sua conta foi bloqueada.” Por quê? E agora?","ten":"O bloqueio protege, mas a pessoa precisa de um caminho de volta.","sol":"Redistribuir a agência: política de desbloqueio pelo próprio usuário, com motivo, prazo e verificação.","c":"C28","u":"U14","e":"macro","i":"I07","m":"Chamados de desbloqueio","freq":2,"imp":3,"pers":2,"pf":"P01","hx":["BS5.2","BS5.3","ISO5","SH7"],"dom":"comunicacao","vul":"","ag":"Ganha: quem teve a conta bloqueada. Perde: a plataforma precisa de fluxo seguro de desbloqueio.","alt":"E se o bloqueio for automático e errado para muita gente?","esc":{"micro":"Explicar o motivo em termos gerais e o prazo.","meso":"Fluxo de desbloqueio pelo próprio usuário com verificação.","macro":"Redistribuir a agência: política de desbloqueio pelo próprio usuário, com motivo, prazo e verificação."},"st":"add","sub":"Retirar a exigência de contatar o suporte para desbloquear.","ops":["U19","U22"],"c2":{"c":"C05","t":"Desbloqueio fácil ajuda invasores.","mit":"Verificação forte (documento, dispositivo conhecido)."},"cf":"Sem intervenção, a pessoa perde o acesso por dias e não sabe por quê.","lim":{"l":"L06","t":"Políticas de segurança da plataforma."},"ide":{"mais":["I07"],"menos":["I05"]},"ref":"Estaria errada se, nos registros, os bloqueios forem sempre por atividade suspeita real.","conf":"alta"},
{"id":415,"h":9,"sev":3,"t":"Erro que some rápido","sym":"No app da casa, a mensagem de erro aparece por 2 segundos e desaparece antes de ser lida.","ten":"O aviso quer ser discreto, mas precisa ser lido.","sol":"Condicionar pelo tipo: erros permanecem até serem resolvidos ou fechados.","c":"C31","u":"U21","e":"micro","i":"I09","m":"Erros repetidos","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS5.2","WC2.2","SH3","ISO6"],"dom":"casa","vul":"","ag":"Ganha: quem configura aparelhos. Perde: mensagens de erro podem se acumular na tela.","alt":"E se a mensagem sumir porque foi feita como notificação de sucesso?","esc":{"micro":"Condicionar pelo tipo: erros permanecem até serem resolvidos ou fechados.","meso":"Tipos de aviso com durações diferentes (sucesso some, erro fica).","macro":"Padrão de mensagens do app: sucesso some sozinho, erro fica até ser resolvido."},"st":"sub","sub":"A própria solução é subtrativa: remove o fechamento automático das mensagens de erro.","ops":["U01","U30"],"c2":{"c":"C17","t":"Erros que ficam acumulam na tela.","mit":"Fechar ao resolver ou manualmente."},"cf":"Sem intervenção, a pessoa repete a ação sem saber o que deu errado.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I09"],"menos":["I03"]},"ref":"Estaria errada se, em teste, as pessoas conseguirem ler a mensagem em 2 segundos.","conf":"alta"},
{"id":416,"h":9,"sev":3,"t":"Erro em inglês","sym":"O assistente de IA em português exibe “Invalid input” e “Rate limit exceeded”.","ten":"A mensagem veio de um componente não traduzido.","sol":"Converter o meio: camada que transforma erros de serviços externos em mensagens próprias em português.","c":"C29","u":"U16","e":"meso","i":"I03","m":"Compreensão da mensagem","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["WC3.1","BS5.2","IA5","ISO3"],"dom":"ia","vul":"baixa escolaridade","ag":"Ganha: quem não lê inglês. Perde: a equipe traduz mensagens de serviços externos.","alt":"E se o erro vier do modelo de IA e não houver controle sobre o texto?","esc":{"micro":"Mensagem própria em português para os erros mais frequentes do modelo.","meso":"Converter o meio: camada que transforma erros de serviços externos em mensagens próprias em português.","macro":"Glossário de erros traduzidos para toda a plataforma."},"st":"add","sub":"Retirar mensagens em inglês da interface.","ops":["U04","U32"],"c2":{"c":"C27","t":"Traduzir automaticamente erros técnicos pode distorcer o sentido.","mit":"Mensagens próprias por tipo de erro, não tradução literal."},"cf":"Sem intervenção, a pessoa não entende o erro e desiste.","lim":{"l":"L03","t":"Erros vindos de APIs externas."},"ide":{"mais":["I03"],"menos":["I02"]},"ref":"Estaria errada se o público do produto ler inglês sem dificuldade.","conf":"média"},
{"id":417,"h":9,"sev":4,"t":"Pagou ou não pagou?","sym":"O erro aparece depois de pagar a passagem e não se sabe se houve cobrança.","ten":"A falha ocorreu entre sistemas, mas o cliente precisa de certeza.","sol":"Triangular o estado real: consultar o processador e dizer claramente “Nenhuma cobrança foi feita” ou “Pagamento confirmado”.","c":"C34","u":"U03","e":"meso","i":"I05","m":"Pagamentos duplicados","freq":2,"imp":3,"pers":2,"pf":"P04","hx":["BS5.2","GP2","SH3","ISO6","MB8"],"dom":"mobilidade","vul":"","ag":"Ganha: viajantes e a central. Perde: consultar o processador em tempo real custa integração.","alt":"E se a incerteza vier de a confirmação do banco chegar só minutos depois?","esc":{"micro":"Mensagem “Estamos confirmando seu pagamento”.","meso":"Triangular o estado real: consultar o processador e dizer claramente “Nenhuma cobrança foi feita” ou “Pagamento confirmado”.","macro":"Consulta automática ao processador e aviso quando confirmar."},"st":"add","sub":"Retirar a mensagem de erro genérica quando o estado do pagamento é desconhecido.","ops":["U01","U20"],"c2":{"c":"C31","t":"Aguardar a confirmação atrasa a emissão.","mit":"Reservar o assento enquanto confirma."},"cf":"Sem intervenção, passageiros pagam duas vezes ou perdem a passagem.","lim":{"l":"L03","t":"Depende do tempo de resposta do processador."},"ide":{"mais":["I05"],"menos":["I02"]},"ref":"Estaria errada se, nos registros, os pagamentos duplicados forem raros.","conf":"alta"},
{"id":418,"h":9,"sev":3,"t":"Sem “Tentar novamente”","sym":"Na teleconsulta, “Falha de conexão” e nenhum botão; é preciso recarregar tudo.","ten":"A falha é temporária, mas a recuperação é manual e completa.","sol":"Escalonar a recuperação: botão “Tentar novamente” que refaz só a ação que falhou.","c":"C30","u":"U31","e":"micro","i":"I08","m":"Recargas de página","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["MB8","BS5.3","SH6","ISO6"],"dom":"saude","vul":"conexão ruim","ag":"Ganha: pacientes em teleconsulta com rede instável. Perde: tentativas automáticas repetidas podem esgotar a bateria.","alt":"E se a conexão cair tanto que o formato de vídeo seja o problema?","esc":{"micro":"Escalonar a recuperação: botão “Tentar novamente” que refaz só a ação que falhou.","meso":"Reconexão automática com aviso.","macro":"Alternativa de áudio ou chat quando o vídeo falhar."},"st":"add","sub":"Retirar a exigência de recarregar a página inteira.","ops":["U22","U19"],"c2":{"c":"C27","t":"Tentativas automáticas repetidas podem esgotar a bateria.","mit":"Poucas tentativas automáticas e botão manual."},"cf":"Sem intervenção, a consulta é interrompida e remarcada.","lim":{"l":"L08","t":"Qualidade da rede do paciente."},"ide":{"mais":["I08"],"menos":["I03"]},"ref":"Estaria errada se as quedas forem raras.","conf":"alta"},
{"id":419,"h":9,"sev":3,"t":"Importação falha sem linha","sym":"No sistema de cadastro: “Erro na importação” numa planilha de 3.000 linhas.","ten":"O erro está em um lugar específico, mas a mensagem é genérica.","sol":"Separar o que funcionou do que falhou: importar as linhas válidas e listar linha, coluna e motivo de cada erro.","c":"C13","u":"U09","e":"meso","i":"I09","m":"Importações abandonadas","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS5.2","BS5.3","GP3","SH3"],"dom":"trabalho","vul":"","ag":"Ganha: quem importa planilhas. Perde: importar as válidas pode deixar a base incompleta sem que se perceba.","alt":"E se os erros vierem de um modelo de planilha desatualizado?","esc":{"micro":"Lista com linha, coluna e motivo.","meso":"Separar o que funcionou do que falhou: importar as linhas válidas e listar linha, coluna e motivo de cada erro.","macro":"Modelo de planilha oficial para download."},"st":"add","sub":"Retirar a rejeição do arquivo inteiro por causa de uma linha.","ops":["U24","U25"],"c2":{"c":"C04","t":"Importar as válidas pode deixar a base incompleta sem que se perceba.","mit":"Resumo claro do que entrou e do que ficou de fora."},"cf":"Sem intervenção, a importação é abandonada.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I09"],"menos":["I03"]},"ref":"Estaria errada se, nos registros, as importações com erro forem raras.","conf":"alta"},
{"id":420,"h":9,"sev":3,"t":"Sem permissão, sem caminho","sym":"Na sala virtual da disciplina: “Acesso negado” e mais nada.","ten":"A permissão existe por um motivo, mas alguém pode concedê-la.","sol":"Redistribuir a agência: dizer quem administra o acesso e oferecer “Solicitar acesso” com um clique.","c":"C22","u":"U14","e":"meso","i":"I07","m":"Tempo até obter acesso","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS5.2","SH7","ISO5","GP2"],"dom":"educacao","vul":"","ag":"Ganha: estudantes e professores. Perde: administradores recebem mais pedidos de acesso.","alt":"E se as permissões forem restritivas demais por padrão?","esc":{"micro":"Mensagem com quem administra o acesso.","meso":"Redistribuir a agência: dizer quem administra o acesso e oferecer “Solicitar acesso” com um clique.","macro":"Permissões padrão revistas por perfil."},"st":"add","sub":"Retirar o “Acesso negado” sem caminho.","ops":["U12","U01"],"c2":{"c":"C17","t":"Pedidos de acesso em excesso sobrecarregam o administrador.","mit":"Agrupar pedidos e aprovar em lote."},"cf":"Sem intervenção, estudantes perdem aulas esperando acesso.","lim":{"l":"L06","t":"Regras de permissão da instituição."},"ide":{"mais":["I07"],"menos":["I05"]},"ref":"Estaria errada se os pedidos de acesso forem raros.","conf":"alta"},
{"id":421,"h":9,"sev":3,"t":"Erro em cascata","sym":"No formulário do portal, um campo errado gera dez mensagens de erro diferentes.","ten":"As validações dependem umas das outras e disparam juntas.","sol":"Isolar a causa: mostrar só o erro de origem e suprimir os derivados.","c":"C12","u":"U23","e":"meso","i":"I03","m":"Tempo de correção","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS5.2","GP8","SH3","LX13"],"dom":"publico","vul":"","ag":"Ganha: cidadãos que preenchem formulários. Perde: erros derivados ficam ocultos até corrigir a causa.","alt":"E se os erros em cascata vierem de validações que dependem umas das outras sem necessidade?","esc":{"micro":"Mostrar só a causa raiz.","meso":"Isolar a causa: mostrar só o erro de origem e suprimir os derivados.","macro":"Revisão das regras de validação do portal."},"st":"sub","sub":"A própria solução é subtrativa: remove os erros derivados.","ops":["U02","U35"],"c2":{"c":"C34","t":"Esconder erros derivados pode esconder um problema independente.","mit":"Mostrar os derivados depois de corrigir a causa."},"cf":"Sem intervenção, dez mensagens assustam e a pessoa não sabe por onde começar.","lim":{"l":"L03","t":"Regras de validação encadeadas."},"ide":{"mais":["I03"],"menos":["I09"]},"ref":"Estaria errada se as cascatas forem raras.","conf":"alta"},
{"id":422,"h":9,"sev":4,"t":"Travamento que perde tudo","sym":"Durante a prova online, o navegador trava e as respostas não salvas desaparecem.","ten":"Falhas acontecem, mas não precisam levar o trabalho junto.","sol":"Memorizar continuamente: cada resposta salva ao ser dada e recuperação do estado ao reabrir.","c":"C06","u":"U36","e":"meso","i":"I10","m":"Trabalho recuperado","freq":2,"imp":3,"pers":2,"pf":"P14","hx":["TG13","MB8","BS5.3","ISO6"],"dom":"educacao","vul":"","ag":"Ganha: estudantes em provas online. Perde: salvar sempre exige armazenamento.","alt":"E se o travamento vier do navegador do estudante, fora do controle da plataforma?","esc":{"micro":"Salvar cada resposta ao responder.","meso":"Memorizar continuamente: cada resposta salva ao ser dada e recuperação do estado ao reabrir.","macro":"Recuperação automática da prova com o tempo preservado."},"st":"add","sub":"Retirar a dependência de um único envio no fim da prova.","ops":["U22","U24"],"c2":{"c":"C05","t":"Respostas salvas podem ser vistas por outros no mesmo computador.","mit":"Salvar no servidor, não no aparelho."},"cf":"Sem intervenção, estudantes perdem a prova e recorrem à coordenação.","lim":{"l":"L03","t":"Estabilidade dos navegadores."},"ide":{"mais":["I10"],"menos":["I02"]},"ref":"Estaria errada se os travamentos forem raros.","conf":"alta"},
{"id":423,"h":9,"sev":3,"t":"Formato recusado, sem conversão","sym":"No portal de exames: “Apenas PNG” — e a foto do exame é JPG.","ten":"O sistema aceita um formato, mas poderia converter os outros.","sol":"Converter o meio: aceitar formatos comuns e converter no servidor para o sistema antigo.","c":"C24","u":"U16","e":"macro","i":"I02","m":"Uploads recusados","freq":2,"imp":2,"pers":2,"pf":"P03","hx":["LX7","BS5.3","SH5","ISO1"],"dom":"saude","vul":"","ag":"Ganha: pacientes que enviam exames. Perde: o sistema converte arquivos no servidor.","alt":"E se o formato exigido existir por um sistema antigo que só lê PNG?","esc":{"micro":"Explicar como converter.","meso":"Conversão no navegador antes do envio.","macro":"Converter o meio: aceitar formatos comuns e converter no servidor para o sistema antigo."},"st":"add","sub":"Retirar a exigência de formato único.","ops":["U13","U33"],"c2":{"c":"C22","t":"Converter pode perder qualidade de exames.","mit":"Guardar também o original."},"cf":"Sem intervenção, pacientes não conseguem enviar exames e ligam para a clínica.","lim":{"l":"L03","t":"Sistema legado da clínica que só lê um formato."},"ide":{"mais":["I02"],"menos":["I03"]},"ref":"Estaria errada se as recusas forem raras.","conf":"média"},
{"id":424,"h":9,"sev":2,"t":"“Inválido” sem exemplo","sym":"No app do banco: “Formato de data inválido” — qual é o válido?","ten":"A regra existe, mas não é mostrada.","sol":"Converter a função da mensagem: ela vira exemplo — “Use DD/MM/AAAA, ex.: 22/09/2026”.","c":"C34","u":"U17","e":"micro","i":"I02","m":"Tentativas por campo","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["BS5.2","WC3.3","GP4","LX7"],"dom":"financas","vul":"","ag":"Ganha: quem preenche datas. Perde: exemplos longos poluem a mensagem.","alt":"E se o formato fosse aceito de qualquer jeito, dispensando a mensagem?","esc":{"micro":"Converter a função da mensagem: ela vira exemplo — “Use DD/MM/AAAA, ex.: 22/09/2026”.","meso":"Aceitar vários formatos de data.","macro":"Padrão de mensagens com exemplo."},"st":"add","sub":"Retirar “inválido” sem exemplo.","ops":["U16","U02"],"c2":{"c":"C17","t":"Exemplos longos poluem a mensagem.","mit":"Um exemplo curto, no formato exato esperado."},"cf":"Sem intervenção, várias tentativas por campo.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I02"],"menos":["I03"]},"ref":"Estaria errada se as pessoas acertarem na segunda tentativa.","conf":"alta"},
{"id":425,"h":9,"sev":4,"t":"Endereço real recusado","sym":"O validador de endereço não reconhece a rua nova e impede a instalação da internet.","ten":"A base de endereços está desatualizada, mas o endereço existe.","sol":"Negociar a restrição: permitir confirmar manualmente endereços não encontrados, com ponto de referência.","c":"C22","u":"U29","e":"micro","i":"I06","m":"Compras bloqueadas","freq":2,"imp":3,"pers":2,"pf":"P09","hx":["LX7","BS5.3","SH2","ISO6"],"dom":"casa","vul":"zona rural","ag":"Ganha: moradores de ruas novas e áreas rurais. Perde: a base aceita endereços não verificados.","alt":"E se a base de endereços desatualizada for o problema, e não a validação?","esc":{"micro":"Negociar a restrição: permitir confirmar manualmente endereços não encontrados, com ponto de referência.","meso":"Confirmação manual com ponto de referência.","macro":"Atualização da base de endereços com dados dos técnicos de campo."},"st":"sub","sub":"A própria solução é subtrativa: remove o bloqueio para endereços não encontrados.","ops":["U22","U19"],"c2":{"c":"C34","t":"Endereços não verificados dificultam a visita do técnico.","mit":"Pedir ponto de referência e telefone."},"cf":"Sem intervenção, famílias em ruas novas não conseguem contratar a instalação.","lim":{"l":"L06","t":"Base de endereços de terceiros."},"ide":{"mais":["I06"],"menos":["I04"]},"ref":"Estaria errada se as recusas forem por endereços realmente inválidos.","conf":"alta"},
{"id":426,"h":9,"sev":2,"t":"Erro que não se pode copiar","sym":"No sistema da empresa, a mensagem técnica está numa janela que não permite selecionar o texto.","ten":"O suporte pede o código do erro, que precisa ser digitado à mão.","sol":"Converter a perda em ganho: botão “Copiar detalhes” que transforma o erro em informação útil para o suporte.","c":"C25","u":"U18","e":"micro","i":"I09","m":"Tempo de atendimento","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["BS5.2","GP1","ISO6","SH3"],"dom":"trabalho","vul":"","ag":"Ganha: quem abre chamados e o suporte. Perde: detalhes copiados podem conter dados sensíveis.","alt":"E se o erro pudesse ser enviado ao suporte automaticamente?","esc":{"micro":"Converter a perda em ganho: botão “Copiar detalhes” que transforma o erro em informação útil para o suporte.","meso":"Botão “Enviar ao suporte” com os detalhes anexados.","macro":"Registro automático de erros com identificador único."},"st":"add","sub":"Retirar a janela que impede selecionar o texto.","ops":["U16","U12"],"c2":{"c":"C05","t":"Detalhes copiados podem conter dados sensíveis.","mit":"Filtrar dados pessoais antes de copiar."},"cf":"Sem intervenção, o suporte recebe códigos digitados errado e demora a resolver.","lim":{"l":"L03","t":"Componente de diálogo do sistema."},"ide":{"mais":["I09"],"menos":["I05"]},"ref":"Estaria errada se, nos registros, os chamados já chegarem com o código correto.","conf":"alta"},
{"id":427,"h":9,"sev":4,"t":"Erro no fim de um fluxo longo","sym":"Na reserva de pacote de viagem, a falha na etapa 6 manda de volta para a etapa 1.","ten":"O erro é pontual, mas a recuperação é total.","sol":"Proteger o progresso: manter tudo o que foi preenchido e retornar só à etapa com problema.","c":"C18","u":"U24","e":"meso","i":"I10","m":"Fluxos refeitos","freq":3,"imp":3,"pers":2,"pf":"P01","hx":["TG13","BS5.3","SH6","ISO6","LX8"],"dom":"mobilidade","vul":"","ag":"Ganha: quem faz reservas longas. Perde: o sistema guarda o estado de cada etapa.","alt":"E se o erro no fim vier de uma validação que poderia ter sido feita no começo?","esc":{"micro":"Manter os dados ao voltar.","meso":"Proteger o progresso: manter tudo o que foi preenchido e retornar só à etapa com problema.","macro":"Validar disponibilidade e dados no início do fluxo."},"st":"sub","sub":"A própria solução é subtrativa: remove o retorno à etapa 1.","ops":["U20","U36"],"c2":{"c":"C36","t":"Dados guardados podem ficar desatualizados (preço mudou).","mit":"Revalidar só o que mudou."},"cf":"Sem intervenção, a pessoa refaz a reserva inteira e muitas desistem.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I10"],"menos":["I02"]},"ref":"Estaria errada se as falhas no fim forem raras.","conf":"alta"},
{"id":428,"h":9,"sev":3,"t":"Link de confirmação expirado","sym":"Na rede social: “Link expirado” — e não há como pedir outro.","ten":"O prazo protege, mas o link antigo não pode ser um beco sem saída.","sol":"Botão “Enviar novo link” na própria página de expiração.","c":"C33","u":"U22","e":"micro","i":"I07","m":"Cadastros não confirmados","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS5.3","SH4","ISO6","MB8"],"dom":"comunicacao","vul":"","ag":"Ganha: quem confirma o cadastro. Perde: reenviar links com facilidade pode ser explorado por abuso.","alt":"E se o link expirar rápido demais para quem confere o e-mail só no dia seguinte?","esc":{"micro":"Botão “Enviar novo link” na própria página de expiração.","meso":"Prazo de validade do link revisto.","macro":"Confirmação por código como alternativa ao link."},"st":"add","sub":"Retirar a página de expiração sem saída.","ops":["U08","U19"],"c2":{"c":"C05","t":"Reenviar links facilmente pode ajudar abusos.","mit":"Limite de reenvios por hora."},"cf":"Sem intervenção, cadastros ficam pela metade.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I07"],"menos":["I05"]},"ref":"Estaria errada se, nos registros, a maioria dos links for usada antes de expirar.","conf":"alta"},
{"id":429,"h":9,"sev":3,"t":"Erro que só aparece no console","sym":"O botão do assistente de IA não faz nada e nenhum erro aparece; a falha está escondida no navegador.","ten":"O sistema registrou a falha, mas não a comunicou.","sol":"Instituir a regra: toda falha de ação gera mensagem visível com próximo passo.","c":"C01","u":"U30","e":"meso","i":"I09","m":"Cliques sem efeito","freq":3,"imp":2,"pers":2,"pf":"P01","hx":["BS5.2","IA2","SH3","BS1.4"],"dom":"ia","vul":"","ag":"Ganha: quem usa o assistente. Perde: a equipe cria mensagens para cada falha.","alt":"E se as falhas silenciosas forem sintoma de erros que a equipe nem monitora?","esc":{"micro":"Mensagem visível para cada falha.","meso":"Instituir a regra: toda falha de ação gera mensagem visível com próximo passo.","macro":"Monitoramento de falhas silenciosas no produto."},"st":"add","sub":"Retirar o tratamento de erros que só registra no console.","ops":["U01","U19"],"c2":{"c":"C17","t":"Mensagens para falhas raras poluem.","mit":"Mensagem genérica com código para as raras."},"cf":"Sem intervenção, a pessoa clica várias vezes e acha que o produto está quebrado.","lim":{"l":"L03","t":"Erros assíncronos difíceis de capturar."},"ide":{"mais":["I09"],"menos":["I03"]},"ref":"Estaria errada se, nos registros, os cliques repetidos sem efeito forem raros.","conf":"alta"},
{"id":430,"h":9,"sev":2,"t":"Arquivo grande demais sem saída","sym":"No app de mensagens: “Arquivo excede 10 MB” e nada mais.","ten":"O limite existe, mas a pessoa precisa enviar aquele arquivo.","sol":"Redistribuir a carga: o app comprime o arquivo ou sugere como reduzir.","c":"C16","u":"U13","e":"micro","i":"I02","m":"Envios concluídos após o erro","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["LX7","BS5.3","GP1","ISO6"],"dom":"comunicacao","vul":"","ag":"Ganha: quem envia fotos e vídeos. Perde: arquivos comprimidos perdem qualidade.","alt":"E se o limite for baixo demais para o uso atual?","esc":{"micro":"Redistribuir a carga: o app comprime o arquivo ou sugere como reduzir.","meso":"Compressão automática com opção de manter o original.","macro":"Limite revisto conforme o uso."},"st":"add","sub":"Retirar a mensagem sem alternativa.","ops":["U16","U29"],"c2":{"c":"C03","t":"Comprimir perde qualidade.","mit":"Mostrar a prévia comprimida antes de enviar."},"cf":"Sem intervenção, a pessoa desiste de enviar.","lim":{"l":"L04","t":"Custo de armazenamento."},"ide":{"mais":["I02"],"menos":["I04"]},"ref":"Estaria errada se os envios concluídos não aumentarem com a compressão.","conf":"alta"},
{"id":431,"h":9,"sev":3,"t":"Reserva presa após falha","sym":"O pagamento do ingresso falha, mas o assento fica reservado e indisponível por horas.","ten":"A reserva protege a compra, mas precisa ser liberada na falha.","sol":"Reverter o efeito: liberar a reserva automaticamente ou manter por tempo curto com aviso para concluir.","c":"C12","u":"U24","e":"meso","i":"I04","m":"Reservas órfãs","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS5.3","SH6","ISO6","LX8"],"dom":"comercio","vul":"","ag":"Ganha: compradores de ingressos. Perde: liberar rápido demais faz perder o ingresso.","alt":"E se a reserva longa existir para evitar que outros comprem durante o pagamento?","esc":{"micro":"Liberar a reserva após falha.","meso":"Reverter o efeito: liberar a reserva automaticamente ou manter por tempo curto com aviso para concluir.","macro":"Política de tempo de reserva com aviso e contagem visível."},"st":"add","sub":"Retirar a reserva presa sem prazo.","ops":["U08","U20"],"c2":{"c":"C17","t":"Liberar rápido demais faz perder o ingresso.","mit":"Tempo curto com aviso."},"cf":"Sem intervenção, ingressos ficam presos e outros não compram.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I04"],"menos":["I02"]},"ref":"Estaria errada se as reservas presas forem raras.","conf":"alta"},
{"id":432,"h":9,"sev":2,"t":"CEP errado sem sugestão","sym":"No cadastro do portal: “CEP não encontrado” após trocar um dígito.","ten":"O erro é pequeno, mas a mensagem trata como beco sem saída.","sol":"Inferir a intenção: sugerir CEPs próximos, buscar pelo endereço e aceitar preenchimento manual.","c":"C04","u":"U02","e":"micro","i":"I02","m":"Cadastros abandonados","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["BS5.3","LX7","GP1","WC3.3"],"dom":"publico","vul":"baixa escolaridade","ag":"Ganha: cidadãos que não sabem o CEP de cor ou erram um dígito. Perde: nada relevante.","alt":"E se a pessoa nem souber o próprio CEP, e o campo obrigatório for a barreira?","esc":{"micro":"Inferir a intenção: sugerir CEPs próximos, buscar pelo endereço e aceitar preenchimento manual.","meso":"Busca de CEP pelo nome da rua e cidade no próprio formulário.","macro":"Base de CEPs atualizada e compartilhada entre os serviços do governo."},"st":"add","sub":"Retirar a mensagem que encerra o cadastro sem alternativa.","ops":["U16","U22"],"c2":{"c":"C27","t":"Sugestões de CEP parecido podem levar a um endereço errado.","mit":"Mostrar a rua e o bairro de cada sugestão para confirmar."},"cf":"Sem intervenção, cadastros são abandonados por um dígito trocado.","lim":{"l":"L06","t":"Base de CEPs mantida por terceiros."},"ide":{"mais":["I02"],"menos":[]},"ref":"Estaria errada se, nos registros, os CEPs recusados forem de endereços que realmente não existem.","conf":"alta"},
{"id":433,"h":9,"sev":4,"t":"Fora do ar sem previsão","sym":"O sistema de agendamento da rede de saúde: “Sistema indisponível.” Até quando?","ten":"A equipe está resolvendo, mas quem usa precisa planejar.","sol":"Antecipar: informar causa geral, previsão de retorno e canal alternativo, numa política de comunicação de incidentes.","c":"C34","u":"U20","e":"macro","i":"I09","m":"Tentativas repetidas","freq":2,"imp":3,"pers":2,"pf":"P06","hx":["BS5.2","GP2","MB1","SH3"],"dom":"saude","vul":"","ag":"Ganha: pacientes que precisam agendar. Perde: a equipe se compromete publicamente com prazos.","alt":"E se a previsão de retorno for impossível de dar em falhas graves?","esc":{"micro":"Mensagem com causa geral e horário do próximo aviso.","meso":"Página de status com histórico de incidentes.","macro":"Antecipar: informar causa geral, previsão de retorno e canal alternativo, numa política de comunicação de incidentes."},"st":"add","sub":"Retirar a mensagem “indisponível” sem nenhuma informação.","ops":["U01","U22"],"c2":{"c":"C27","t":"Previsões erradas desgastam mais que o silêncio.","mit":"Faixa de tempo e atualização a cada hora."},"cf":"Sem intervenção, pacientes tentam de novo a cada minuto e lotam a central telefônica.","lim":{"l":"L06","t":"Comunicação oficial de incidentes pela rede de saúde."},"ide":{"mais":["I09"],"menos":["I05"]},"ref":"Estaria errada se, nos registros, as tentativas repetidas não diminuírem com a previsão.","conf":"média"},
{"id":434,"h":9,"sev":4,"t":"Captcha sem alternativa","sym":"Na venda de ingressos, o captcha só tem imagens; quem não enxerga não consegue passar.","ten":"A proteção precisa ser acessível a todas as pessoas.","sol":"Variar as modalidades: alternativa em áudio ou verificação sem desafio visual, como política de acessibilidade.","c":"C25","u":"U34","e":"macro","i":"I06","m":"Bloqueios por acessibilidade","freq":2,"imp":3,"pers":2,"pf":"P09","hx":["WC1.1","WC2.5","SH2","DP2","BS5.3"],"dom":"comercio","vul":"cegos (leitor de tela)","ag":"Ganha: pessoas cegas e com baixa visão. Perde: a loja depende de verificação menos visual.","alt":"E se o captcha visual existir por custo, e não por necessidade de segurança?","esc":{"micro":"Alternativa em áudio ao lado do captcha visual.","meso":"Verificação sem desafio visual (comportamento, e-mail).","macro":"Variar as modalidades: alternativa em áudio ou verificação sem desafio visual, como política de acessibilidade."},"st":"sub","sub":"A própria solução é subtrativa: remove o captcha visual como única barreira.","ops":["U21","U29"],"c2":{"c":"C05","t":"Alternativas mais fáceis também ajudam robôs.","mit":"Combinar sinais de comportamento com limite de tentativas."},"cf":"Sem intervenção, pessoas cegas não conseguem comprar ingressos sozinhas.","lim":{"l":"L06","t":"Lei brasileira de inclusão."},"ide":{"mais":["I06"],"menos":["I05"]},"ref":"Estaria errada se, em teste com leitor de tela, o captcha atual puder ser resolvido.","conf":"alta"},
{"id":435,"h":9,"sev":3,"t":"Erro sem contraste","sym":"No app do banco, o texto de erro é vermelho claro sobre fundo rosa, quase invisível.","ten":"A cor sinaliza alerta, mas precisa de contraste para ser lida.","sol":"Instituir a regra: cores de erro com contraste adequado, ícone e texto claro.","c":"C02","u":"U30","e":"micro","i":"I06","m":"Erros não percebidos","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["WC1.4","TG14","BS5.2","TG3"],"dom":"financas","vul":"baixa visão","ag":"Ganha: clientes com baixa visão. Perde: nada relevante.","alt":"E se as cores de erro vierem de uma paleta de marca que nunca foi testada?","esc":{"micro":"Instituir a regra: cores de erro com contraste adequado, ícone e texto claro.","meso":"Tokens de erro com contraste verificado em todo o app.","macro":"Verificação automática de contraste a cada publicação."},"st":"mod","sub":"Retirar o vermelho claro sobre rosa.","ops":["U16","U19"],"c2":{"c":"C17","t":"Cores de erro fortes demais assustam.","mit":"Contraste suficiente com tom sóbrio."},"cf":"Sem intervenção, erros não são percebidos por quem enxerga pouco.","lim":{"l":"L06","t":"Paleta definida pela marca."},"ide":{"mais":["I06"],"menos":[]},"ref":"Estaria errada se a verificação mostrar contraste acima de 4,5:1.","conf":"alta"},
{"id":436,"h":9,"sev":4,"t":"Conflito de versão descartado","sym":"No editor da equipe, duas edições conflitaram e uma foi descartada em silêncio.","ten":"O sistema escolheu por conta própria, mas a decisão era da pessoa.","sol":"Comparar as duas versões lado a lado e deixar a pessoa escolher ou mesclar.","c":"C35","u":"U26","e":"meso","i":"I10","m":"Trabalho perdido em conflitos","freq":2,"imp":3,"pers":2,"pf":"P07","hx":["SH6","TG13","BS5.3","ISO5"],"dom":"trabalho","vul":"","ag":"Ganha: equipes que editam os mesmos documentos. Perde: a pessoa precisa decidir entre versões.","alt":"E se os conflitos forem frequentes porque o trabalho offline é comum?","esc":{"micro":"Aviso de conflito com as duas versões.","meso":"Comparar as duas versões lado a lado e deixar a pessoa escolher ou mesclar.","macro":"Edição em tempo real que evita a maioria dos conflitos."},"st":"add","sub":"Retirar o descarte silencioso de uma das versões.","ops":["U14","U24"],"c2":{"c":"C31","t":"Decidir entre versões interrompe o trabalho.","mit":"Mesclar automaticamente o que não conflita."},"cf":"Sem intervenção, trabalho é perdido sem que ninguém saiba.","lim":{"l":"L03","t":"Sincronização offline."},"ide":{"mais":["I10"],"menos":["I02"]},"ref":"Estaria errada se os conflitos forem raros.","conf":"média"},
{"id":437,"h":9,"sev":3,"t":"Erro que expõe dados internos","sym":"A tela de erro da loja mostra caminhos do servidor e trechos de código.","ten":"O detalhe técnico ajuda a depurar, mas expõe o sistema.","sol":"Mensagem amigável ao usuário; detalhes técnicos registrados apenas para a equipe.","c":"C23","u":"U23","e":"macro","i":"I05","m":"Exposições em auditoria","freq":1,"imp":3,"pers":2,"pf":"P01","hx":["BS5.2","SH3","ISO6","GP8"],"dom":"comercio","vul":"","ag":"Ganha: clientes e a segurança da loja. Perde: o suporte precisa de outro meio para diagnosticar.","alt":"E se os detalhes aparecerem porque o servidor está em modo de desenvolvimento?","esc":{"micro":"Mensagem amigável com código de referência para o suporte.","meso":"Detalhes técnicos só nos registros internos.","macro":"Mensagem amigável ao usuário; detalhes técnicos registrados apenas para a equipe."},"st":"sub","sub":"A própria solução é subtrativa: remove os detalhes técnicos da tela.","ops":["U09","U30"],"c2":{"c":"C34","t":"Sem os detalhes na tela, o suporte precisa de outro meio para diagnosticar.","mit":"Código de referência na mensagem que liga aos registros."},"cf":"Sem intervenção, a loja expõe caminhos internos a atacantes.","lim":{"l":"L06","t":"Normas de segurança exigem não expor detalhes do servidor."},"ide":{"mais":["I05"],"menos":["I09"]},"ref":"Estaria errada se, em auditoria, nenhuma página mostrar detalhes técnicos.","conf":"alta"},
{"id":438,"h":9,"sev":2,"t":"Senha incorreta sem ver o que foi digitado","sym":"No app do roteador, “senha incorreta” três vezes, sem opção de ver o que foi digitado.","ten":"Ocultar protege de olhares, mas impede conferir.","sol":"Botão para mostrar a senha digitada.","c":"C34","u":"U01","e":"micro","i":"I02","m":"Tentativas de login","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["BS5.3","SH8","ISO6","WC3.3"],"dom":"casa","vul":"idosos","ag":"Ganha: quem configura o roteador, sobretudo idosos. Perde: a senha fica visível por um instante.","alt":"E se a senha do roteador for longa demais para digitar sem erro?","esc":{"micro":"Botão para mostrar a senha digitada.","meso":"Mostrar a senha por padrão em telas privadas (configuração em casa).","macro":"Senha do roteador trocável por QR code."},"st":"add","sub":"Retirar a ocultação obrigatória da senha.","ops":["U16","U21"],"c2":{"c":"C05","t":"Mostrar a senha expõe em público.","mit":"Botão para mostrar, não mostrar sempre."},"cf":"Sem intervenção, tentativas repetidas e bloqueio do roteador.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I02"],"menos":["I05"]},"ref":"Estaria errada se, nos registros, os erros de senha forem raros.","conf":"alta"},
{"id":439,"h":9,"sev":3,"t":"Compartilhado, mas sem acesso","sym":"No sistema da empresa, o documento foi enviado, mas o destinatário não consegue abrir.","ten":"A permissão não acompanhou o envio, e ninguém avisou.","sol":"Antecipar: avisar no envio que a pessoa não tem acesso e oferecer conceder na hora.","c":"C10","u":"U20","e":"meso","i":"I07","m":"Pedidos de acesso","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS5.1","GP2","SH3","ISO6"],"dom":"trabalho","vul":"","ag":"Ganha: quem compartilha e quem recebe. Perde: conceder acesso na hora pode expor o documento sem querer.","alt":"E se o documento devesse ser compartilhado com permissão já no envio?","esc":{"micro":"Aviso no momento do envio: “Esta pessoa não tem acesso”.","meso":"Antecipar: avisar no envio que a pessoa não tem acesso e oferecer conceder na hora.","macro":"Compartilhar concede o acesso automaticamente."},"st":"add","sub":"Retirar o envio de links sem acesso.","ops":["U12","U14"],"c2":{"c":"C05","t":"Conceder acesso automático pode expor dados.","mit":"Perguntar antes de conceder."},"cf":"Sem intervenção, pedidos de acesso e atrasos.","lim":{"l":"L06","t":"Políticas de compartilhamento."},"ide":{"mais":["I07"],"menos":["I05"]},"ref":"Estaria errada se, nos registros, os pedidos de acesso forem raros.","conf":"alta"},
{"id":440,"h":9,"sev":3,"t":"CPF já cadastrado sem saída","sym":"No portal: “CPF já cadastrado” e a pessoa não lembra de ter conta.","ten":"O sistema impede duplicidade, mas não ajuda a recuperar a conta existente.","sol":"Reacoplar à conta existente: oferecer recuperá-la, mostrando o e-mail parcialmente.","c":"C05","u":"U12","e":"macro","i":"I07","m":"Contas recuperadas","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS5.3","SH3","ISO6","WC3.3"],"dom":"publico","vul":"","ag":"Ganha: cidadãos que esqueceram a conta. Perde: mostrar dados da conta expõe informações.","alt":"E se o CPF estiver cadastrado por outra pessoa (fraude)?","esc":{"micro":"Mostrar o e-mail parcial.","meso":"Recuperar a conta vinculada.","macro":"Reacoplar à conta existente: oferecer recuperá-la, mostrando o e-mail parcialmente."},"st":"add","sub":"Retirar a mensagem que encerra o cadastro.","ops":["U22","U02"],"c2":{"c":"C05","t":"Mostrar dados da conta expõe informações.","mit":"Parte mínima e verificação."},"cf":"Sem intervenção, contas duplicadas e suporte sobrecarregado.","lim":{"l":"L06","t":"Normas do governo digital."},"ide":{"mais":["I07"],"menos":["I05"]},"ref":"Estaria errada se, nos registros, as pessoas lembrarem da conta.","conf":"alta"},
{"id":441,"h":9,"sev":4,"t":"Cartão recusado na renovação sem aviso","sym":"O streaming é suspenso porque o cartão venceu, sem aviso antes.","ten":"A cobrança é automática, mas o problema é previsível.","sol":"Antecipar: avisar sobre cartão a vencer e falhas, com prazo para atualizar antes de suspender.","c":"C33","u":"U20","e":"macro","i":"I11","m":"Suspensões evitadas","freq":2,"imp":3,"pers":2,"pf":"P06","hx":["BS5.1","GP1","TG1","SH3"],"dom":"comunicacao","vul":"","ag":"Ganha: assinantes. Perde: a empresa envia mais avisos.","alt":"E se a suspensão imediata existir para pressionar o pagamento?","esc":{"micro":"Aviso quando o cartão estiver para vencer.","meso":"Prazo para atualizar antes de suspender.","macro":"Antecipar: avisar sobre cartão a vencer e falhas, com prazo para atualizar antes de suspender."},"st":"add","sub":"Retirar a suspensão imediata após a primeira falha.","ops":["U08","U22"],"c2":{"c":"C17","t":"Avisos em excesso viram ruído.","mit":"Poucos avisos, em momentos certos."},"cf":"Sem intervenção, o serviço é cortado sem aviso e o cliente cancela.","lim":{"l":"L06","t":"Regras de cobrança e de suspensão do contrato."},"ide":{"mais":["I11"],"menos":["I02"]},"ref":"Estaria errada se os cartões vencidos forem raros.","conf":"alta"},
{"id":442,"h":9,"sev":4,"t":"Página técnica de erro 500","sym":"Ao enviar a reserva, aparece uma página branca com “Internal Server Error”.","ten":"A falha é do servidor, mas quem sofre é o usuário.","sol":"Reverter o dano: página de erro amigável que preserva o que foi digitado e oferece tentar de novo, como padrão da plataforma.","c":"C09","u":"U24","e":"macro","i":"I04","m":"Envios perdidos","freq":2,"imp":3,"pers":2,"pf":"P01","hx":["BS5.3","TG13","SH6","ISO6"],"dom":"mobilidade","vul":"","ag":"Ganha: quem envia formulários longos. Perde: página amigável esconde o problema técnico da equipe.","alt":"E se o erro 500 for frequente porque o servidor está sobrecarregado?","esc":{"micro":"Página de erro amigável.","meso":"Preservar o que foi digitado e tentar de novo.","macro":"Reverter o dano: página de erro amigável que preserva o que foi digitado e oferece tentar de novo, como padrão da plataforma."},"st":"add","sub":"Retirar a página técnica do servidor.","ops":["U22","U19"],"c2":{"c":"C34","t":"Página amigável esconde o problema técnico da equipe.","mit":"Registro automático e alerta à equipe."},"cf":"Sem intervenção, reservas perdidas e reclamações.","lim":{"l":"L03","t":"Infraestrutura do servidor."},"ide":{"mais":["I04"],"menos":["I03"]},"ref":"Estaria errada se os erros 500 forem raros.","conf":"alta"},
{"id":443,"h":9,"sev":2,"t":"Erro aponta para ajuda quebrada","sym":"A mensagem de erro do app de mensagens tem “Saiba mais”, que leva a uma página que não existe.","ten":"A mensagem quer ajudar, mas o link envelheceu.","sol":"Verificação automática de links nas mensagens e na ajuda.","c":"C36","u":"U19","e":"meso","i":"I04","m":"Links quebrados","freq":2,"imp":1,"pers":2,"pf":"P01","hx":["BS5.2","SH3","ISO6","TG13"],"dom":"comunicacao","vul":"","ag":"Ganha: quem lê a ajuda. Perde: nada relevante.","alt":"E se os artigos forem apagados sem redirecionamento?","esc":{"micro":"Corrigir os links quebrados.","meso":"Verificação automática de links nas mensagens e na ajuda.","macro":"Verificação automática de links a cada publicação."},"st":"add","sub":"Retirar links para artigos removidos.","ops":["U36","U30"],"c2":{"c":"C17","t":"Alertas de links quebrados em excesso.","mit":"Agrupar por gravidade."},"cf":"Sem intervenção, a mensagem de erro leva a outra página de erro.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I04"],"menos":[]},"ref":"Estaria errada se, em auditoria, nenhum link de mensagem estiver quebrado.","conf":"alta"},
{"id":444,"h":9,"sev":3,"t":"“Não entendi” sem sugestão","sym":"O assistente de voz responde “Não entendi” repetidamente.","ten":"O assistente tem vocabulário limitado, mas não o revela.","sol":"Sondar e sugerir: exemplos de pedidos que funcionam e alternativa por toque.","c":"C35","u":"U25","e":"micro","i":"I08","m":"Pedidos resolvidos","freq":2,"imp":2,"pers":2,"pf":"P10","hx":["IA1","IA10","BS5.3","SH3"],"dom":"ia","vul":"idosos","ag":"Ganha: quem usa o assistente de voz, sobretudo idosos. Perde: nada relevante.","alt":"E se o assistente não entender porque o vocabulário é limitado demais?","esc":{"micro":"Sondar e sugerir: exemplos de pedidos que funcionam e alternativa por toque.","meso":"Opção de tocar em vez de falar.","macro":"Treinamento com frases reais dos usuários."},"st":"add","sub":"Retirar o “Não entendi” sem saída.","ops":["U02","U22"],"c2":{"c":"C17","t":"Exemplos em excesso cansam.","mit":"Dois exemplos de frases que o assistente entende."},"cf":"Sem intervenção, idosos desistem do assistente.","lim":{"l":"L03","t":"Reconhecimento de voz."},"ide":{"mais":["I08"],"menos":[]},"ref":"Estaria errada se, nos registros, os pedidos resolvidos não aumentarem com as sugestões.","conf":"média"},
{"id":445,"h":9,"sev":3,"t":"Falha ao gerar PDF sem motivo","sym":"No portal de exames: “Não foi possível gerar o laudo em PDF.”","ten":"A causa é conhecida pelo sistema (arquivo grande, imagem inválida), mas não é dita.","sol":"Reenquadrar a falha: dizer o motivo e a correção (reduzir o período, tentar mais tarde).","c":"C34","u":"U04","e":"meso","i":"I09","m":"Exportações bem-sucedidas","freq":2,"imp":2,"pers":2,"pf":"P04","hx":["BS5.2","GP2","SH3","ISO6"],"dom":"saude","vul":"","ag":"Ganha: pacientes. Perde: nada relevante.","alt":"E se o motivo for sempre o mesmo (arquivo grande)?","esc":{"micro":"Mensagem com o motivo da falha e o que fazer.","meso":"Reenquadrar a falha: dizer o motivo e a correção (reduzir o período, tentar mais tarde).","macro":"Registro dos motivos de falha."},"st":"add","sub":"Retirar a mensagem sem motivo.","ops":["U01","U19"],"c2":{"c":"C17","t":"Motivos técnicos confundem.","mit":"Motivo em linguagem simples, sem termos técnicos."},"cf":"Sem intervenção, pacientes não conseguem o laudo.","lim":{"l":"L03","t":"Nenhuma barreira técnica relevante."},"ide":{"mais":["I09"],"menos":[]},"ref":"Estaria errada se as falhas forem raras.","conf":"alta"},
{"id":446,"h":9,"sev":3,"t":"Várias abas, sessão confusa","sym":"No internet banking, ao sair numa aba, as outras continuam aceitando ações que depois falham.","ten":"As abas compartilham a sessão, mas não se comunicam.","sol":"Condicionar pelo estado da sessão: sincronizar as abas e avisar em todas quando a sessão terminar.","c":"C05","u":"U21","e":"meso","i":"I04","m":"Ações perdidas","freq":2,"imp":2,"pers":2,"pf":"P08","hx":["BS5.3","SH3","ISO6","WC3.2"],"dom":"financas","vul":"","ag":"Ganha: clientes que usam o internet banking em várias abas. Perde: sincronizar abas pode encerrar uma operação em andamento em outra aba.","alt":"E se as várias abas forem abertas justamente porque o sistema não permite comparar telas lado a lado?","esc":{"micro":"Aviso em todas as abas quando a sessão terminar.","meso":"Condicionar pelo estado da sessão: sincronizar as abas e avisar em todas quando a sessão terminar.","macro":"Estado de sessão compartilhado entre abas, com saída sincronizada."},"st":"add","sub":"Retirar a aceitação de ações em abas cuja sessão já terminou.","ops":["U12","U01"],"c2":{"c":"C27","t":"Sincronizar abas pode encerrar uma operação em andamento em outra aba.","mit":"Avisar e preservar o que estava sendo feito antes de encerrar."},"cf":"Sem intervenção, transferências preenchidas numa aba antiga falham sem explicação.","lim":{"l":"L03","t":"Comunicação entre abas depende do navegador."},"ide":{"mais":["I04"],"menos":["I02"]},"ref":"Estaria errada se, nos registros, quase ninguém usar o internet banking em mais de uma aba.","conf":"alta"},
{"id":447,"h":9,"sev":2,"t":"Campo opcional que bloqueia","sym":"No checkout, o campo opcional “Complemento” mal preenchido impede o envio do pedido.","ten":"O campo não é necessário, mas é validado como se fosse.","sol":"Negociar a restrição: validar opcionais só se preenchidos, sem bloquear o essencial.","c":"C23","u":"U29","e":"micro","i":"I02","m":"Envios bloqueados","freq":2,"imp":1,"pers":2,"pf":"P09","hx":["BS5.1","WC3.3","LX7","SH5"],"dom":"comercio","vul":"","ag":"Ganha: clientes que finalizam compras. Perde: dados opcionais malformados podem passar se preenchidos com erro.","alt":"E se o campo opcional nem devesse existir no checkout?","esc":{"micro":"Negociar a restrição: validar opcionais só se preenchidos, sem bloquear o essencial.","meso":"Revisão de todos os campos opcionais do checkout.","macro":"Regra de validação: opcionais só validados quando preenchidos."},"st":"sub","sub":"A própria solução é subtrativa: remove a validação de campos opcionais vazios.","ops":["U35","U21"],"c2":{"c":"C22","t":"Um opcional preenchido com erro pode passar sem validação.","mit":"Validar o formato só quando houver conteúdo."},"cf":"Sem intervenção, compras travam por causa de um campo que a pessoa nem precisava preencher.","lim":{"l":"L03","t":"Regras de validação do formulário."},"ide":{"mais":["I02"],"menos":["I04"]},"ref":"Estaria errada se, nos registros, os envios bloqueados vierem de campos obrigatórios.","conf":"alta"},
{"id":448,"h":9,"sev":3,"t":"Horário ocupado só ao confirmar","sym":"No agendamento: depois de preencher tudo, “Este horário não está mais disponível”.","ten":"A agenda muda, mas a verificação acontece tarde.","sol":"Separar no tempo: reservar temporariamente o horário ao selecioná-lo e verificar em tempo real.","c":"C17","u":"U08","e":"meso","i":"I02","m":"Agendamentos refeitos","freq":2,"imp":2,"pers":2,"pf":"P08","hx":["BS5.1","SH5","ISO6","TG1"],"dom":"saude","vul":"","ag":"Ganha: pacientes que agendam. Perde: horários ficam presos por alguns minutos durante o agendamento.","alt":"E se a agenda for tão disputada que qualquer reserva temporária prejudique outros pacientes?","esc":{"micro":"Aviso “Outra pessoa está vendo este horário”.","meso":"Separar no tempo: reservar temporariamente o horário ao selecioná-lo e verificar em tempo real.","macro":"Reserva temporária do horário por alguns minutos ao selecioná-lo."},"st":"add","sub":"Retirar a verificação de disponibilidade só na confirmação final.","ops":["U20","U19"],"c2":{"c":"C17","t":"Reservas temporárias prendem horários de quem desiste no meio.","mit":"Tempo curto (5 minutos) com contagem visível."},"cf":"Sem intervenção, pacientes preenchem tudo e perdem o horário no último clique.","lim":{"l":"L03","t":"Concorrência de acessos à agenda."},"ide":{"mais":["I02"],"menos":["I06"]},"ref":"Estaria errada se, nos registros, a perda de horário na confirmação for rara.","conf":"alta"},
{"id":449,"h":9,"sev":3,"t":"“Contate o administrador” — quem?","sym":"A mensagem do sistema manda “contatar o administrador”, sem dizer quem é.","ten":"A orientação é correta, mas incompleta.","sol":"Reacoplar a pessoa ao responsável: mostrar quem administra ou enviar o pedido direto a ele.","c":"C10","u":"U12","e":"meso","i":"I07","m":"Tempo até resolução","freq":2,"imp":2,"pers":2,"pf":"P01","hx":["BS5.2","SH3","GP2","ISO2"],"dom":"trabalho","vul":"","ag":"Ganha: funcionários que precisam de acesso. Perde: administradores recebem pedidos diretos.","alt":"E se o administrador mudar com frequência e o nome ficar desatualizado?","esc":{"micro":"Nome e contato do administrador na mensagem.","meso":"Reacoplar a pessoa ao responsável: mostrar quem administra ou enviar o pedido direto a ele.","macro":"Pedido de acesso enviado automaticamente ao responsável atual."},"st":"add","sub":"Retirar a instrução vaga “contate o administrador”.","ops":["U14","U01"],"c2":{"c":"C05","t":"Expor nomes e e-mails de administradores atrai pedidos indevidos.","mit":"Canal de pedido em vez do contato pessoal."},"cf":"Sem intervenção, funcionários perdem horas descobrindo quem pode liberar o acesso.","lim":{"l":"L06","t":"Estrutura de responsabilidades da TI."},"ide":{"mais":["I07"],"menos":["I02"]},"ref":"Estaria errada se, nos registros, os pedidos de acesso forem resolvidos rapidamente mesmo sem o nome.","conf":"alta"},
{"id":450,"h":9,"sev":2,"t":"Sem como relatar um problema","sym":"Ao encontrar uma resposta errada do assistente de IA, não há canal para contar.","ten":"A equipe quer melhorar, mas não ouve quem encontra os erros.","sol":"Retroalimentar a equipe: botão “Relatar problema” que anexa contexto técnico com consentimento.","c":"C28","u":"U19","e":"macro","i":"I12","m":"Problemas relatados","freq":2,"imp":1,"pers":3,"pf":"P11","hx":["BS5.2","IA15","ISO7","SH3"],"dom":"ia","vul":"","ag":"Ganha: quem usa o assistente e a equipe, que descobre falhas. Perde: a equipe precisa triar relatos.","alt":"E se os relatos chegarem, mas ninguém na equipe os ler?","esc":{"micro":"Botão “Relatar problema” em cada resposta.","meso":"Relato com contexto técnico anexado (com consentimento).","macro":"Retroalimentar a equipe: botão “Relatar problema” que anexa contexto técnico com consentimento."},"st":"add","sub":"Retirar a ausência de canal para relatar erros.","ops":["U27","U36"],"c2":{"c":"C17","t":"Relatos em excesso sobrecarregam a equipe.","mit":"Triagem automática por tipo e frequência."},"cf":"Sem intervenção, falhas do assistente se repetem sem que a equipe saiba.","lim":{"l":"L06","t":"Processo interno para tratar os relatos."},"ide":{"mais":["I12"],"menos":["I02"]},"ref":"Estaria errada se, depois do botão, os relatos não levarem a nenhuma correção em três meses.","conf":"média"}
);
